      var rs = (r.store || '').trim();
      if (!rs) return false;
      if (sv.indexOf(rs) >= 0 || rs.indexOf(sv) >= 0) return true;
      var parts = rs.split('-');
      var namePart = (parts[0] || '').trim();
      var locPart = (parts.slice(1).join('-') || '').trim();
      return namePart && sv.indexOf(namePart) === 0 && (!locPart || sv.indexOf(locPart) >= 0);
